import itertools, json
Aopts = ["KMP","LNP","KLN","MQR","LMQ"]
Bopts = ["LPQ","NPR","LMP","MNR","KNP"]
Adays = [{2,7},{1,6,7},{7},{8},{2,7}]
Bdays = [{4,6},{3},{2,8},{3},{6,7,8}]
As = [a for a in itertools.product(*Aopts) if len(set(a)) == 5]
Bs = [b for b in itertools.product(*Bopts) if len(set(b)) == 5]
counts = {}
witness = {}
total = 0
for a in As:
    for b in Bs:
        common = set(a) & set(b)
        if len(common) != 3 or len(common & set("KPR")) != 1:
            continue
        attendance = {p:set() for p in "KLMNPQR"}
        for p, days in zip(a, Adays):
            attendance[p].update(days)
        for p, days in zip(b, Bdays):
            attendance[p].update(days)
        n = sum(len(days) >= 3 for days in attendance.values())
        total += 1
        counts[n] = counts.get(n,0) + 1
        witness.setdefault(n, {"A":"".join(a),"B":"".join(b)})
lo, hi = min(counts), max(counts)
print(json.dumps({"feasible_linkages":total,"bounds":[lo,hi],"low_witness":witness[lo],"high_witness":witness[hi],"decision":"confirmed" if lo>=4 else "excluded" if hi<4 else "undetermined"}))
print("distribution", counts)
print("witness attendance")
for k in [lo,hi]:
    w=witness[k]
    att={p:set() for p in "KLMNPQR"}
    for p,d in zip(w["A"],Adays): att[p].update(d)
    for p,d in zip(w["B"],Bdays): att[p].update(d)
    print(k,{p:sorted(d) for p,d in att.items()})

